const QUESTIONS=[{"question":"¿Cuáles tres puntos son colineales?","options":["E, B y N","D, C y N","E, D y C"],"correct":1,"image":0,"explanation":"D, C y N están sobre la misma recta horizontal.","original":1},{"question":"¿Cuál es el punto de intersección de las rectas ED y CN?","options":["E","B","D"],"correct":2,"image":0,"explanation":"La recta ED cruza la recta CN en D. Una recta se extiende en ambos sentidos.","original":2},{"question":"¿Cuál segmento tiene por extremo el punto B?","options":["ED","CN","EB"],"correct":2,"image":0,"explanation":"Los extremos del segmento EB son E y B.","original":3},{"question":"¿Cuál recta es perpendicular a la recta AE?","options":["HA","BE","ED"],"correct":0,"image":1,"explanation":"HA y AE forman un ángulo recto en A, indicado por el pequeño cuadrado.","original":4},{"question":"¿Cuáles rectas son concurrentes en D?","options":["HA y AE","HA y HB","BD y ED"],"correct":2,"image":1,"explanation":"Las rectas BD y ED se encuentran en el punto D.","original":5},{"question":"¿Cuál es el punto de intersección de las rectas HD y BE?","options":["H","D","B"],"correct":2,"image":1,"explanation":"B pertenece tanto a la recta horizontal HD como a la recta BE.","original":6},{"question":"¿Cuál ángulo forma un par lineal con ∠11?","options":["∠8","∠10","∠2"],"correct":2,"image":2,"explanation":"∠11 y ∠2 comparten un lado y sus otros lados son rayos opuestos; suman 180°.","original":7},{"question":"¿Cuál ángulo es opuesto por el vértice a ∠8?","options":["∠9","∠11","∠2"],"correct":1,"image":2,"explanation":"∠8 y ∠11 quedan enfrentados al cruzarse las mismas dos rectas.","original":8},{"question":"¿Cuál ángulo es adyacente a ∠8?","options":["∠2","∠10","∠11"],"correct":0,"image":2,"explanation":"∠8 y ∠2 comparten vértice y un lado, sin superponerse.","original":9},{"question":"¿Cuál ángulo es suplementario de ∠B?","options":["∠A","∠D","∠C"],"correct":2,"image":3,"explanation":"∠B mide 55° y ∠C mide 125°: 55° + 125° = 180°.","original":10},{"question":"¿Cuál ángulo es congruente con ∠D?","options":["∠A","∠B","∠C"],"correct":1,"image":3,"explanation":"∠B y ∠D miden 55°; por eso son congruentes.","original":11},{"question":"¿Cuál ángulo es complementario de ∠B?","options":["∠A","∠B","∠C"],"correct":0,"image":3,"explanation":"∠A mide 35°: 35° + 55° = 90°.","original":12},{"question":"¿Cuál es la medida del ángulo β?","options":["56°","112°","180°"],"correct":0,"image":4,"explanation":"Las marcas señalan dos ángulos iguales. Entonces 2β + 68° = 180°; β = 112° ÷ 2 = 56°.","original":13},{"question":"¿Cuál es la medida del ángulo θ?","options":["72°","108°","180°"],"correct":0,"image":5,"explanation":"Los ángulos opuestos por el vértice son congruentes: θ = 72°.","original":14},{"question":"A, N y C son colineales, en ese orden. ¿Cuánto mide ∠DNC?","options":["76°","104°","180°"],"correct":1,"image":6,"explanation":"∠AND y ∠DNC forman un ángulo llano: 180° − 76° = 104°.","original":15},{"question":"¿Cuál terna puede representar las longitudes de los lados de un triángulo?","options":["I: 6, 9 y 16","II: 7, 10 y 12","III: 4, 8 y 12"],"correct":1,"image":null,"explanation":"La suma de los dos lados menores debe superar al mayor. I: 6 + 9 < 16, no sirve. II: 7 + 10 > 12, sí sirve. III: 4 + 8 = 12, no sirve.","original":16},{"question":"Dos lados de un triángulo miden 11 y 17. ¿Cuál puede ser la medida del tercer lado?","options":["I: 6","II: 15","III: 28"],"correct":1,"image":null,"explanation":"El tercer lado x debe cumplir 17 − 11 < x < 17 + 11, es decir, 6 < x < 28. Solo 15 cumple.","original":17},{"question":"¿Cuál es la medida del ángulo θ?","options":["64°","58°","116°"],"correct":1,"image":7,"explanation":"Los dos ángulos marcados son iguales. θ = (180° − 64°) ÷ 2 = 58°.","original":18},{"question":"¿Cuál es la medida del ángulo θ?","options":["34°","68°","112°"],"correct":0,"image":8,"explanation":"Los dos ángulos marcados son iguales. θ = (180° − 112°) ÷ 2 = 34°.","original":19},{"question":"¿Cuál es la medida del ángulo α?","options":["49°","62°","69°"],"correct":2,"image":9,"explanation":"Los ángulos internos del triángulo suman 180°: α = 180° − 62° − 49° = 69°.","original":20},{"question":"¿Cuál es la medida del ángulo exterior β?","options":["64°","58°","122°"],"correct":2,"image":10,"explanation":"Los ángulos internos marcados son iguales: α = (180° − 64°) ÷ 2 = 58°. Luego β = 180° − 58° = 122°.","original":21},{"question":"¿Cuál es la medida del ángulo θ del cuadrilátero?","options":["85°","95°","360°"],"correct":0,"image":11,"explanation":"Los ángulos internos suman 360°: θ = 360° − 102° − 81° − 92° = 85°.","original":22},{"question":"En la figura, B, C y E están alineados. ¿Cuál es la medida de α?","options":["60°","120°","180°"],"correct":1,"image":12,"explanation":"Las tres marcas indican que ABC es equilátero, por lo que θ = 60°. Como B, C y E están alineados, α = 180° − 60° = 120°.","original":23},{"question":"¿Cuál es la medida de β?","options":["64°","120°","180°"],"correct":0,"image":12,"explanation":"En el cuadrilátero ACED, α = 120°. Por tanto β = 360° − 68° − 108° − 120° = 64°.","original":24}];